"""Offline, escaped HTML report with client-side filtering."""
from html import escape


def render(findings, before='Baseline', after='Candidate'):
    counts = {s: sum(f.severity == s for f in findings) for s in ('breaking', 'warning', 'info')}
    rows = ''.join(f'<article data-severity="{f.severity}"><span class="badge {f.severity}">{f.severity}</span><div><h3>{escape(f.code.replace("_", " ").title())}</h3><code>{escape(f.location)}</code><p>{escape(f.message)}</p></div></article>' for f in findings)
    cards = ''.join(f'<div class="stat"><strong>{n}</strong><span>{s.title()}</span></div>' for s, n in counts.items())
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ContractLens • Compatibility report</title>
<style>
:root{color-scheme:dark;--bg:#0c1220;--panel:#141e31;--muted:#a0aec3;--line:#29364c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#eef3fa;font:16px/1.6 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:50px 24px}header{border-bottom:1px solid var(--line);padding-bottom:32px}.brand{color:#79e5c0;font-weight:800;letter-spacing:.15em;font-size:13px}h1{font-size:clamp(34px,6vw,64px);line-height:1.1;margin:20px 0}h2{font-size:23px}h3{margin:0;font-size:17px}p{color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:30px 0}.stat{background:var(--panel);border:1px solid var(--line);padding:24px;border-radius:16px}.stat strong{display:block;font-size:42px}.stat span{color:var(--muted)}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}input,select{font:inherit;background:var(--panel);color:inherit;border:1px solid var(--line);padding:12px;border-radius:9px}input{flex:1;min-width:180px}article{display:flex;align-items:flex-start;gap:24px;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:24px;margin:12px 0}article[hidden]{display:none}.badge{font-size:12px;text-transform:uppercase;padding:4px 9px;border-radius:6px;min-width:84px;text-align:center}.breaking{background:#542532;color:#ffafbc}.warning{background:#493c22;color:#f8d38a}.info{background:#183f38;color:#8ce6cb}code{font-size:13px;color:#93b7fb;overflow-wrap:anywhere}footer{margin-top:40px;font-size:13px;color:var(--muted)}.comparison{overflow-wrap:anywhere}@media(max-width:600px){article{display:block}.badge{display:inline-block;margin-bottom:12px}.stat{padding:15px}.stat strong{font-size:30px}}
</style><main><header><div class="brand">◈ CONTRACTLENS</div><h1>Change with confidence.</h1><p>API compatibility evidence for existing clients.</p><div class="comparison">''' + escape(before) + ' → ' + escape(after) + '''</div></header><section class="stats" aria-label="Finding counts">''' + cards + '''</section><h2>Compatibility findings</h2><p>Supported checks only. Review warnings and scope limitations before releasing.</p><div class="toolbar"><input id="search" type="search" aria-label="Search findings" placeholder="Search endpoints, rules, or messages"><select id="severity" aria-label="Filter severity"><option value="all">All severities</option><option>breaking</option><option>warning</option><option>info</option></select></div><p id="visible" aria-live="polite"></p><section>''' + (rows or '<p>No changes detected by supported checks.</p>') + '''</section><footer>ContractLens · Local analysis · No tracking or external assets · OpenAPI 3.0 JSON subset</footer></main><script>
const search=document.getElementById('search'), severity=document.getElementById('severity');function filter(){let count=0;document.querySelectorAll('article').forEach(row=>{row.hidden=!(severity.value==='all'||row.dataset.severity===severity.value)||!row.textContent.toLowerCase().includes(search.value.toLowerCase());if(!row.hidden)count++});document.getElementById('visible').textContent=count+' findings shown'}search.addEventListener('input',filter);severity.addEventListener('change',filter);filter();
</script></html>'''
